// Sandbox verification: prove the correct projectActivity payload shape
// and verify whether name is even needed alongside activityType.
const BASE = "https://kkpqfuj-amager.tripletex.dev/v2";
const TOKEN = "eyJ0b2tlbklkIjoyMTQ3NjI4NDYxLCJ0b2tlbiI6IjU2NDRjNDljLWU0YzYtNGU2OC05MWU5LWU0MzBhMWRiYTMzYSJ9";
const AUTH = "Basic " + btoa(`0:${TOKEN}`);
const TODAY = "2026-03-21";
const RND = Math.floor(Math.random() * 100000000);

async function api(method: string, path: string, body?: any) {
  const url = `${BASE}${path}`;
  const opts: RequestInit = {
    method,
    headers: { Authorization: AUTH, "Content-Type": "application/json" },
  };
  if (body) opts.body = JSON.stringify(body);
  const res = await fetch(url, opts);
  const text = await res.text();
  let json: any;
  try { json = JSON.parse(text); } catch { json = text; }
  console.log(`${method} ${path} => ${res.status}`);
  if (!res.ok) {
    console.error(JSON.stringify(json, null, 2));
  }
  return { ok: res.ok, status: res.status, json };
}

async function main() {
  // Step 1: parallel — GET department, GET division, POST customer
  const [deptRes, divRes, custRes] = await Promise.all([
    api("GET", "/department?isInactive=false&count=1&fields=*"),
    api("GET", "/division?count=1&fields=*"),
    api("POST", "/customer", {
      name: `Sandbox Lifecycle ${RND} AS`,
      organizationNumber: "857400526",
      isCustomer: true,
    }),
  ]);

  const deptId = deptRes.json.values?.[0]?.id;
  const divId = divRes.json.values?.[0]?.id;
  if (!custRes.ok) { console.error("Customer create failed"); return; }
  const customerId = custRes.json.value.id;
  console.log(`Customer: ${customerId}, Dept: ${deptId}, Div: ${divId ?? "none"}`);

  const makeEmployment = (startDate: string) => {
    const emp: any = { startDate };
    if (divId) emp.division = { id: divId };
    return emp;
  };

  // Step 2: POST first employee
  const emp1Res = await api("POST", "/employee", {
    firstName: "Sandbox",
    lastName: `Test1 ${RND}`,
    email: `sandbox1.${RND}@example.org`,
    userType: "NO_ACCESS",
    dateOfBirth: "1990-01-15",
    department: deptId ? { id: deptId } : undefined,
    employments: [makeEmployment(TODAY)],
  });
  if (!emp1Res.ok) { console.error("Employee 1 failed"); return; }
  const emp1Id = emp1Res.json.value.id;

  // Step 3: parallel — GET assignable managers, POST second employee
  const [mgrRes, emp2Res] = await Promise.all([
    api("GET", "/employee?assignableProjectManagers=true&count=1&fields=*"),
    api("POST", "/employee", {
      firstName: "Sandbox",
      lastName: `Test2 ${RND}`,
      email: `sandbox2.${RND}@example.org`,
      userType: "NO_ACCESS",
      dateOfBirth: "1992-06-20",
      department: deptId ? { id: deptId } : undefined,
      employments: [makeEmployment(TODAY)],
    }),
  ]);
  if (!mgrRes.ok || !emp2Res.ok) { console.error("Step 3 failed"); return; }
  const managerId = mgrRes.json.values[0].id;
  const emp2Id = emp2Res.json.value.id;

  // Step 4: POST project
  const projRes = await api("POST", "/project", {
    name: `Sandbox Project ${RND}`,
    startDate: TODAY,
    customer: { id: customerId },
    projectManager: { id: managerId },
  });
  if (!projRes.ok) { console.error("Project create failed"); return; }
  const projectId = projRes.json.value.id;

  // ======== TEST VARIANTS for POST /project/projectActivity ========

  // Test A: activityType only (no name)
  console.log("\n=== Test A: activityType only, no name ===");
  const testA = await api("POST", "/project/projectActivity", {
    project: { id: projectId },
    startDate: TODAY,
    budgetFeeCurrency: 100000,
    activity: {
      activityType: "PROJECT_SPECIFIC_ACTIVITY",
      isChargeable: false,
    },
  });
  if (testA.ok) {
    console.log("Test A PASSED — activityType alone works without name");
    console.log(`Activity ID: ${testA.json.value.activity.id}, Budget: ${testA.json.value.budgetFeeCurrency}`);
    console.log(`Activity name returned: "${testA.json.value.activity.name}"`);
  } else {
    console.log("Test A FAILED — activityType alone is not enough");
  }

  // Need a second project to test variant B since each project can only have one activity of same type
  const proj2Res = await api("POST", "/project", {
    name: `Sandbox Project B ${RND}`,
    startDate: TODAY,
    customer: { id: customerId },
    projectManager: { id: managerId },
  });
  if (!proj2Res.ok) { console.error("Project 2 create failed"); return; }
  const project2Id = proj2Res.json.value.id;

  // Test B: name only (no activityType) — expected to fail based on prod error
  console.log("\n=== Test B: name only, no activityType ===");
  const testB = await api("POST", "/project/projectActivity", {
    project: { id: project2Id },
    startDate: TODAY,
    budgetFeeCurrency: 100000,
    activity: {
      name: "PROJECT_SPECIFIC_ACTIVITY",
      isChargeable: false,
    },
  });
  if (testB.ok) {
    console.log("Test B PASSED — name alone also works (unexpected)");
    console.log(`Activity name returned: "${testB.json.value.activity.name}"`);
  } else {
    console.log("Test B FAILED — name alone not enough (confirmed)");
  }

  // If test A passed, continue with full lifecycle to verify call count
  if (testA.ok) {
    const activityId = testA.json.value.activity.id;

    // Step 6: parallel — timesheet batch + supplier
    const timesheetEntries = [
      { employee: { id: emp1Id }, activity: { id: activityId }, project: { id: projectId }, date: "2026-03-21", hours: 24 },
      { employee: { id: emp1Id }, activity: { id: activityId }, project: { id: projectId }, date: "2026-03-22", hours: 13 },
      { employee: { id: emp2Id }, activity: { id: activityId }, project: { id: projectId }, date: "2026-03-21", hours: 24 },
      { employee: { id: emp2Id }, activity: { id: activityId }, project: { id: projectId }, date: "2026-03-22", hours: 24 },
      { employee: { id: emp2Id }, activity: { id: activityId }, project: { id: projectId }, date: "2026-03-23", hours: 14 },
    ];

    const [tsRes, supplierRes] = await Promise.all([
      api("POST", "/timesheet/entry/list", timesheetEntries),
      api("POST", "/supplier", {
        name: `Sandbox Supplier ${RND} AS`,
        organizationNumber: "941830420",
        isSupplier: true,
      }),
    ]);

    if (!tsRes.ok) { console.error("Timesheet batch failed"); }
    if (!supplierRes.ok) { console.error("Supplier create failed"); }

    if (tsRes.ok) {
      const totalEmp1 = tsRes.json.values.filter((e: any) => e.employee?.id === emp1Id).reduce((s: number, e: any) => s + e.hours, 0);
      const totalEmp2 = tsRes.json.values.filter((e: any) => e.employee?.id === emp2Id).reduce((s: number, e: any) => s + e.hours, 0);
      console.log(`Timesheet totals — Emp1: ${totalEmp1}h, Emp2: ${totalEmp2}h`);
    }

    // Step 7: parallel — cost + vatType + bank account
    const [costRes, vatRes, bankRes] = await Promise.all([
      api("POST", "/project/orderline", {
        project: { id: projectId },
        description: "Supplier cost",
        date: TODAY,
        count: 1,
        unitCostCurrency: 56300,
        isChargeable: false,
      }),
      api("GET", `/ledger/vatType?typeOfVat=OUTGOING&vatDate=${TODAY}&fields=*`),
      api("GET", "/ledger/account?isBankAccount=true&fields=*"),
    ]);

    if (!costRes.ok || !vatRes.ok || !bankRes.ok) { console.error("Step 7 partial failure"); }

    const vatTypeId = vatRes.json.values?.[0]?.id;
    const bankAccount = bankRes.json.values?.[0];
    console.log(`VAT: ${vatTypeId}, Bank: ${bankAccount?.id}, BankNumber: ${bankAccount?.bankAccountNumber ?? "MISSING"}`);

    // Step 8: bank repair if needed
    if (bankAccount && !bankAccount.bankAccountNumber) {
      console.log("Repairing bank account...");
      await api("PUT", `/ledger/account/${bankAccount.id}`, {
        ...bankAccount,
        bankAccountNumber: "12345678903",
      });
    }

    // Step 9: invoice
    const invoiceRes = await api("POST", "/invoice?sendToCustomer=false", {
      invoiceDate: TODAY,
      invoiceDueDate: "2026-04-20",
      customer: { id: customerId },
      orders: [{
        customer: { id: customerId },
        project: { id: projectId },
        orderDate: TODAY,
        deliveryDate: TODAY,
        orderLines: [{
          description: "Project services",
          count: 1,
          unitPriceExcludingVatCurrency: 100000,
          vatType: { id: vatTypeId },
        }],
      }],
    });

    if (invoiceRes.ok) {
      console.log("\n=== FULL LIFECYCLE VERIFIED ===");
      console.log(`Invoice ID: ${invoiceRes.json.value.id}`);
      console.log(`Amount: ${invoiceRes.json.value.amountExcludingVatCurrency}`);
      console.log(`ProjectInvoiceDetails: ${JSON.stringify(invoiceRes.json.value.projectInvoiceDetails)}`);
    }
  }

  console.log("\n=== SANDBOX VERIFICATION COMPLETE ===");
}

main().catch((e) => {
  console.error("FATAL:", e);
  process.exit(1);
});

